{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "spec@1",
  "id": "SPEC-PRISM-001-CORE",
  "purpose": "Defines the evaluation task models, execution driver interfaces, pluggable harness adapters, and hermetic CoW sandbox environments for Prism.",
  "scope": "Covers crates/prism-core: TaskSpec, VcrCassette, ExecutionDriver trait, HarnessAdapter trait, ClaudeCliDriver, AgyCliDriver, OpenAiCompatibleDriver, OpenCodeDriver, VcrReplayDriver, WorkspaceSandbox with Reflink/APFS CoW and POSIX setpgid process group reaping.",
  "non_goals": [
    "Assertion evaluation logic or grading rules (delegated to prism-grader).",
    "CLI argument parsing or terminal table rendering (delegated to prism-cli)."
  ],
  "api_surface": [
    {
      "name": "TaskSpec",
      "signature": "pub struct TaskSpec { pub id: CompactString, pub skill: CompactString, pub input_prompt: String, pub fixture_repo: Option<PathBuf>, pub expected_assertions: Vec<CompactString>, pub max_turns: usize, pub timeout_seconds: u64 }",
      "description": "Evaluation task definition containing the input prompt, private fixture repository path, expected assertions, and turn limits.",
      "error_conditions": []
    },
    {
      "name": "ExecutionDriver",
      "signature": "pub trait ExecutionDriver: Send + Sync { fn name(&self) -> &'static str; fn is_available(&self) -> bool; async fn execute(&self, task: &TaskSpec, sandbox_dir: &std::path::Path) -> Result<CanonicalTranscript, PrismCoreError>; }",
      "description": "Pluggable driver interface implemented by ClaudeCliDriver, AgyCliDriver, OpenAiCompatibleDriver, OpenCodeDriver, and VcrReplayDriver.",
      "error_conditions": [
        "PrismCoreError::DriverUnavailable if required binary or API key is absent",
        "PrismCoreError::CassetteNotFound if VCR cassette does not exist",
        "PrismCoreError::ProcessFailed if subprocess execution exits with error"
      ]
    },
    {
      "name": "OpenAiCompatibleDriver",
      "signature": "pub struct OpenAiCompatibleDriver { pub base_url: CompactString, pub model_name: CompactString, pub api_key_env: CompactString }; impl OpenAiCompatibleDriver { pub fn qwen_coder(model: &str) -> Self; pub fn kimi(model: &str) -> Self; pub fn glm(model: &str) -> Self; pub fn gemini(model: &str) -> Self; }",
      "description": "Generic streaming driver for any OpenAI-compatible API or local server (Qwen, Kimi, GLM, Gemini, DeepSeek, vLLM, Ollama, LM Studio).",
      "error_conditions": []
    },
    {
      "name": "OpenCodeDriver",
      "signature": "pub struct OpenCodeDriver { pub binary_path: CompactString, pub model_name: CompactString }",
      "description": "Headless CLI driver for executing tasks inside OpenCode / OpenHands environments.",
      "error_conditions": []
    },
    {
      "name": "WorkspaceSandbox",
      "signature": "pub struct WorkspaceSandbox { _temp_dir: tempfile::TempDir, pub path: std::path::PathBuf }; impl WorkspaceSandbox { pub fn new(fixture_path: &std::path::Path) -> Result<Self, std::io::Error>; pub async fn git_checkout(&self, commit_sha: &str) -> Result<(), std::io::Error>; pub async fn apply_patch(&self, patch: &str) -> Result<(), std::io::Error>; pub async fn run_test_suite(&self) -> Result<bool, std::io::Error>; }",
      "description": "Hermetic file sandbox creating isolated /tmp/ workspace clones with Reflink/APFS Copy-on-Write cloning and POSIX process group tree reaping on timeout.",
      "error_conditions": [
        "std::io::Error if disk space is exhausted or file copying fails"
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-PRISM-100",
      "criterion": "WHEN WorkspaceSandbox is initialized with a fixture path, THE SYSTEM SHALL clone the fixture files into a temporary /tmp/ directory using Reflink/APFS Copy-on-Write and initialize a clean git repository.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-101",
      "criterion": "WHEN WorkspaceSandbox drops out of scope or times out, THE SYSTEM SHALL terminate all child processes in the POSIX process group (setpgid) and delete the temporary directory automatically.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-102",
      "criterion": "WHEN VcrReplayDriver executes with matching cassette, THE SYSTEM SHALL deserialize the CanonicalTranscript and return in under 5 milliseconds with $0.00 network spend.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-103",
      "criterion": "WHEN ClaudeCliDriver executes, THE SYSTEM SHALL invoke the local claude CLI using -p and --output-format=json in non-interactive mode.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-104",
      "criterion": "WHEN OpenAiCompatibleDriver executes, THE SYSTEM SHALL dispatch standard /v1/chat/completions payload with Bearer authentication and parse response tokens via CodexAdapter.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-105",
      "criterion": "WHEN OpenCodeDriver executes, THE SYSTEM SHALL invoke the opencode binary with run --task and --json flags.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-106",
      "criterion": "IF an offline task cannot locate a matching cassette file, THE SYSTEM SHALL return PrismCoreError::CassetteNotFound with the expected cassette path.",
      "is_error_case": true,
      "judgment_call": false
    }
  ],
  "linked_requirement": "REQ-PRISM-001",
  "linked_research": "RES-PRISM-001",
  "spec_file_path": "specs/SPEC-PRISM-001-CORE.json",
  "reasoning": "Establishes evaluation task structures, multi-model execution drivers (Claude, AGY, OpenAI-compatible, OpenCode), and hermetic CoW sandboxing."
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "spec@1",
  "id": "SPEC-PRISM-002-GRADER",
  "purpose": "Defines the 4 decoupled evaluation grader engines and the multi-dimensional matrix evaluation and differential comparison engine for Prism.",
  "scope": "Covers crates/prism-grader: Grader trait, AssertionResult, RedGreenGrader, TrajectoryGrader, CircuitBreakerGrader, CalibratedJudge, MatrixResultDatum, MetricDifferential, and eval-report@1 schema formatting.",
  "non_goals": [
    "Subprocess spawning or API networking (delegated to prism-core drivers).",
    "CLI rendering or command dispatch (delegated to prism-cli)."
  ],
  "api_surface": [
    {
      "name": "Grader",
      "signature": "pub trait Grader: Send + Sync { fn name(&self) -> &'static str; fn evaluate(&self, spec: &TaskSpec, transcript: &CanonicalTranscript) -> Result<AssertionResult, EvaluationError>; }",
      "description": "Assertion evaluation interface implemented by the four grading engines.",
      "error_conditions": [
        "EvaluationError::TaskRunnerFailed if test suite fails execution",
        "EvaluationError::AssertionFailed if an assertion is violated"
      ]
    },
    {
      "name": "RedGreenGrader",
      "signature": "pub struct RedGreenGrader; impl RedGreenGrader { pub async fn verify_transition(&self, sandbox: &WorkspaceSandbox) -> Result<AssertionResult, EvaluationError>; }",
      "description": "Verifies that an injected bug or failing test caused the suite to FAIL initially (Red Pass) and that the agent's code made it PASS with zero regressions (Green Pass).",
      "error_conditions": [
        "Fails if initial state passed or final state failed"
      ]
    },
    {
      "name": "TrajectoryGrader",
      "signature": "pub struct TrajectoryGrader { pub min_cache_hit_ratio: f32, pub max_circular_loops: usize }; impl Grader for TrajectoryGrader { ... }",
      "description": "Grades the prompt cache hit percentage (threshold >= 90.0%) and asserts zero Tarjan SCC circular loops.",
      "error_conditions": []
    },
    {
      "name": "CircuitBreakerGrader",
      "signature": "pub struct CircuitBreakerGrader { pub max_allowed_rounds: usize }; impl Grader for CircuitBreakerGrader { ... }",
      "description": "Asserts that multi-agent consensus iterations between reviewer pairs do not exceed 2 rounds.",
      "error_conditions": []
    },
    {
      "name": "MatrixResultDatum",
      "signature": "pub struct MatrixResultDatum { pub config_id: CompactString, pub model_name: CompactString, pub harness_name: CompactString, pub prompt_or_skill: CompactString, pub pass_rate: f64, pub cache_hit_ratio: f64, pub total_cost_usd: f64, pub turn_count: usize, pub turn_latency_p50_ms: u64, pub turn_latency_p95_ms: u64, pub total_wall_time_ms: u64, pub input_tokens: u64, pub output_tokens: u64, pub quality_score: f64, pub circular_loops_detected: usize }; impl MatrixResultDatum { pub fn from_execution(...) -> Self; }",
      "description": "Comprehensive 8-dimensional evaluation metric record for a cell in the experiment matrix.",
      "error_conditions": []
    },
    {
      "name": "MetricDifferential",
      "signature": "pub struct MetricDifferential { pub candidate_id: CompactString, pub baseline_id: CompactString, pub delta_pass_rate_pct: f64, pub delta_cost_pct: f64, pub delta_turns_pct: f64, pub delta_cache_hit_pct: f64, pub delta_wall_time_pct: f64, pub delta_quality_pct: f64 }; impl MetricDifferential { pub fn compute(candidate: &MatrixResultDatum, baseline: &MatrixResultDatum) -> Self; }",
      "description": "Data-vs-data differential calculating exact metric deltas between a candidate variant and a baseline control.",
      "error_conditions": []
    },
    {
      "name": "build_eval_report",
      "signature": "pub fn build_eval_report(eval_id: &str, task: &TaskSpec, transcript: &CanonicalTranscript, assertions: Vec<AssertionResult>) -> serde_json::Value",
      "description": "Assembles the final scorecard into a JSON object strictly conforming to eval-report@1 schema.",
      "error_conditions": []
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-PRISM-120",
      "criterion": "WHEN RedGreenGrader evaluates a state transition, THE SYSTEM SHALL assert that the test runner fails before the patch and succeeds after the patch.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-121",
      "criterion": "IF the test suite passes prior to patch application in a RedGreenGrader trial, THE SYSTEM SHALL mark the Red-to-Green assertion as FAILED with an InvalidRedState message.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-122",
      "criterion": "WHEN TrajectoryGrader evaluates a transcript with a prompt cache hit ratio below min_cache_hit_ratio (default 0.90), THE SYSTEM SHALL mark the Cache Health assertion as FAILED.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-123",
      "criterion": "WHEN TrajectoryGrader observes a CircularLoopAnomaly in the transcript, THE SYSTEM SHALL mark the Trajectory Integrity assertion as FAILED.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-124",
      "criterion": "WHEN CircuitBreakerGrader evaluates review iterations between Drafter and Auditor, THE SYSTEM SHALL assert that total rounds are <= 2.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-125",
      "criterion": "WHEN MatrixResultDatum::from_execution is invoked, THE SYSTEM SHALL calculate all 8 dimensions (Pass rate, cache hit %, cost, turns, latency p50/p95, wall time, input/output tokens, and composite quality score).",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-126",
      "criterion": "WHEN MetricDifferential::compute is invoked, THE SYSTEM SHALL compute exact empirical percentage deltas between candidate and baseline.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-PRISM-127",
      "criterion": "WHEN build_eval_report generates output, THE SYSTEM SHALL validate that the resulting JSON payload validates 100% against the eval-report@1 JSON Schema.",
      "is_error_case": false,
      "judgment_call": false
    }
  ],
  "linked_requirement": "REQ-PRISM-001",
  "linked_research": "RES-PRISM-001",
  "spec_file_path": "specs/SPEC-PRISM-002-GRADER.json",
  "reasoning": "Specifies the 4 decoupled evaluation grader engines, the 8-dimensional matrix metrics, and data-vs-data differential calculations."
}

