}

impl OpenAiCompatibleDriver {
    pub fn new(base_url: impl Into<CompactString>, model_name: impl Into<CompactString>, api_key_env: impl Into<CompactString>) -> Self {
        Self {
            base_url: base_url.into(),
            model_name: model_name.into(),
            api_key_env: api_key_env.into(),
        }
    }

    /// Preconfigured constructor for Qwen 2.5 Coder via DashScope or local vLLM.
    pub fn qwen_coder(model: &str) -> Self {
        Self::new("https://dashscope.aliyuncs.com/compatible-mode/v1", model, "DASHSCOPE_API_KEY")
    }

    /// Preconfigured constructor for Kimi / Moonshot AI.
    pub fn kimi(model: &str) -> Self {
        Self::new("https://api.moonshot.cn/v1", model, "MOONSHOT_API_KEY")
    }

    /// Preconfigured constructor for GLM-4 / Zhipu AI.
    pub fn glm(model: &str) -> Self {
        Self::new("https://open.bigmodel.cn/api/paas/v4", model, "ZHIPUAI_API_KEY")
    }

    /// Preconfigured constructor for Google Gemini 2.0 Flash/Pro via Google's OpenAI-compatible endpoint.
    pub fn gemini(model: &str) -> Self {
        Self::new("https://generativelanguage.googleapis.com/v1beta/openai", model, "GEMINI_API_KEY")
    }
}

#[async_trait]
impl ExecutionDriver for OpenAiCompatibleDriver {
    fn name(&self) -> &'static str {
        "openai-compatible"
    }

    fn is_available(&self) -> bool {
        std::env::var(self.api_key_env.as_str()).is_ok()
    }

    async fn execute(&self, task: &TaskSpec, sandbox_dir: &Path) -> Result<CanonicalTranscript, PrismCoreError> {
        let api_key = std::env::var(self.api_key_env.as_str())
            .map_err(|_| PrismCoreError::DriverUnavailable(format!("Environment variable {} not set", self.api_key_env)))?;

        let payload = serde_json::json!({
            "model": self.model_name.as_str(),
            "messages": [
                { "role": "system", "content": "You are an autonomous AI coding assistant. Execute tasks hermetically." },
                { "role": "user", "content": task.input_prompt.as_str() }
            ],
            "max_tokens": 4096,
            "temperature": 0.0
        });

        let endpoint = format!("{}/chat/completions", self.base_url.trim_end_matches('/'));

        let output = Command::new("curl")
            .arg("-s")
            .arg("-X")
            .arg("POST")
            .arg(&endpoint)
            .arg("-H")
            .arg("Content-Type: application/json")
            .arg("-H")
            .arg(format!("Authorization: Bearer {}", api_key))
            .arg("-d")
            .arg(payload.to_string())
            .current_dir(sandbox_dir)
            .output()
            .await?;

        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(PrismCoreError::ProcessFailed(format!(
                "OpenAI-compatible request failed: {}",
                stderr
            )));
        }

        let cursor = Cursor::new(output.stdout);
        let transcript = CodexAdapter
            .parse_stream(Box::new(cursor))
            .map_err(|e| PrismCoreError::ProcessFailed(format!("Failed to parse response: {}", e)))?;

        Ok(transcript)
    }
}
