            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(PrismCoreError::ProcessFailed(format!(
                "OpenCode failed with code {:?}: {}",
                output.status.code(),
                stderr
            )));
        }

        let cursor = Cursor::new(output.stdout);
        let transcript = ClaudeCodeAdapter
            .parse_stream(Box::new(cursor))
            .map_err(|e| PrismCoreError::ProcessFailed(format!("Failed to parse response: {}", e)))?;

        Ok(transcript)
    }
}

