  "signature": "pub struct SchemaExtractorAccumulator { pub extracted: Vec<SchemaCitation> }; impl SchemaExtractorAccumulator { pub fn update(&mut self, entry: &CanonicalTurn); pub fn finalize(self) -> Vec<SchemaCitation>; }",
  "description": "Extracts and validates embedded JSON schema artifacts (spec@1, plan@1, changeset@1, eval-report@1) against Draft-07 schemas.",
  "error_conditions": [
    "Flags is_valid = false if extracted JSON violates schema"
  ]
