input.new_string:
{
  "name": "SchemaExtractorAccumulator",
  "signature": "pub enum SchemaValidationResult { Valid, Invalid, UnrecognizedSchema }; pub trait SchemaValidator: Send + Sync { fn schema_id(&self) -> &str; fn validate(&self, payload: &serde_json::Value) -> bool; } pub struct SchemaExtractorAccumulator { pub validators: Vec<Box<dyn SchemaValidator>>, pub extracted: Vec<SchemaCitation> }; impl SchemaExtractorAccumulator { pub fn update(&mut self, entry: &CanonicalTurn); pub fn finalize(self) -> Vec<SchemaCitation>; } pub struct SchemaCitation { pub schema_id: CompactString, pub turn_index: usize, pub result: SchemaValidationResult }",
  "description": "Generic $schema/$id-driven extraction with a pluggable per-schema-ID validator registry, tri-state result (Valid/Invalid/UnrecognizedSchema) instead of a boolean. Detection is generic (any embedded JSON block carrying a $schema or $id key), not hardcoded to Lumen's own 5 known schema IDs -- other plugin ecosystems will use different schema formats entirely, so the extraction layer must not assume any specific ecosystem's vocabulary. Validators register per schema_id; a schema ID with no registered validator yields UnrecognizedSchema (not Invalid -- absence of a validator is not evidence of a malformed payload).",
  "error_conditions": [
    "UnrecognizedSchema when no SchemaValidator is registered for the extracted schema_id -- distinct from Invalid, which requires a registered validator that actually rejected the payload"
  ]
},

