      "description": "A single tool invocation node in the trajectory graph, carrying the grounded target file/symbol used for cycle and grounding-score analysis.",
      "error_conditions": []
    },
    {
      "name": "CircularLoopAnomaly",
      "signature": "pub struct CircularLoopAnomaly { pub symbol: CompactString, pub cycle_depth: usize }",
      "description": "Records a detected Tarjan SCC cycle of >= 3 nodes sharing an identical target_symbol with zero state mutations.",
      "error_conditions": []
    },
    {
      "name": "TrajectoryGraph",
      "signature": "pub struct TrajectoryGraph { pub graph: petgraph::graph::DiGraph<ToolNode, ()>, pub last_node: Option<NodeIndex>, pub total_mutations: usize, pub total_reads: usize }; impl TrajectoryGraph { pub fn new() -> Self; pub fn push_tool(&mut self, node: ToolNode) -> NodeIndex; pub fn detect_circular_loops(&self) -> Vec<CircularLoopAnomaly>; pub fn calculate_efficiency(&self) -> f32; pub fn calculate_monotonicity(&self) -> f32; }",
      "description": "Directed graph representation of agent execution paths built by pushing ToolNodes in turn order; detect_circular_loops runs petgraph's Tarjan SCC to find cyclic tool loops and redundant file exploration.",
      "error_conditions": []
    },
    {
      "name": "compute_grounding_score",
      "signature": "pub fn compute_grounding_score(transcript: &CanonicalTranscript) -> f32",
      "description": "Computes Argument Grounding Score G = (Grounded Tool Args) / (Total Invocations). Returns 1.0 when total_tools == 0 (no division by zero).",
      "error_conditions": ["Returns 1.0 (not NaN/panic) when total_tools == 0."]
    },
    {
      "name": "compute_recovery_index",
      "signature": "pub fn compute_recovery_index(transcript: &CanonicalTranscript) -> f32",
      "description": "Computes the Error Recovery Index R = adaptive_error_pivots / total_error_events, where an adaptive error pivot is an error on turn i followed by no error on turn i+1. Returns 1.0 when total_error_events == 0 (no division by zero).",
      "error_conditions": ["Returns 1.0 (not NaN/panic) when total_error_events == 0."]
    },
    {
      "name": "calculate_monotonicity",
      "signature": "pub fn calculate_monotonicity(transcript: &CanonicalTranscript) -> f32",
      "description": "Convenience helper that builds a TrajectoryGraph from a transcript's tool calls in turn order and computes the monotonicity coefficient M in [0.0, 1.0], measuring whether execution avoided circular exploration loops.",
      "error_conditions": []
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-LUMEN-070",
      "criterion": "WHEN a transcript contains 3 identical view_file invocations on the same path without interleaving mutations, THE SYSTEM SHALL identify a Tarjan SCC cyclic loop and emit a CycleAnomaly.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-071",
      "criterion": "WHEN computing resolution monotonicity M on a linear pass transcript with zero backtracking, THE SYSTEM SHALL return M = 1.0.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-072",
      "criterion": "WHEN compute_recovery_index(transcript) is invoked on a transcript where an error occurs on turn i and no error occurs on turn i+1 (1 adaptive error pivot out of 1 total error event), THE SYSTEM SHALL return Error Recovery Index R = adaptive_error_pivots / total_error_events = 1.0.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-073",
      "criterion": "WHEN compute_grounding_score is executed, THE SYSTEM SHALL compute the ratio of tool argument values grounded in prior user or tool outputs versus hallucinated values.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-074",
      "criterion": "IF a transcript has 0 or 1 turns, THE SYSTEM SHALL return monotonicity M = 1.0 and grounding score = 1.0 without dividing by zero.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-155",
      "criterion": "WHEN calculate_monotonicity(transcript) is invoked on a transcript containing 3 consecutive tool invocations that share the same grounded target file or symbol with no interleaving mutation, THE SYSTEM SHALL return M < 1.0, reflecting a detected circular exploration loop.",
