    "Active code execution or test running (handled by prism-core).",
    "Persisting or incrementally updating discovered category clusters across process restarts (discover_fingerprint_corpus recomputes clustering from the full in-memory transcript corpus supplied on each call)."
  ],
  "api_surface": [
    {
      "name": "WorkflowClassifier",
      "signature": "pub struct WorkflowClassifier; impl WorkflowClassifier { pub fn classify_seed(transcript: &CanonicalTranscript) -> Vec<CategoryScore>; pub fn discover_fingerprint(transcript: &CanonicalTranscript, corpus: &[CanonicalTranscript]) -> Option<DiscoveredCategory>; pub fn discover_fingerprint_corpus(corpus: &[CanonicalTranscript]) -> Vec<DiscoveredCategory>; pub fn classify_bimodal(transcript: &CanonicalTranscript) -> BimodalMode; }",
      "description": "Classifies session transcripts into seed categories (feature_dev, bug_hunt, refactoring, test_authoring, eval) and discovers new category clusters. discover_fingerprint looks up which cluster (if any) a single transcript belongs to within a supplied corpus; discover_fingerprint_corpus computes the full clustering over that corpus in one pass.",
      "error_conditions": []
    },
    {
      "name": "BimodalMode",
      "signature": "pub enum BimodalMode { Acceleration, Exploration, Balanced }",
      "description": "Classifies a session's dominant interaction pattern: Acceleration (high mutation density, low search activity), Exploration (high search activity, high turn count), or Balanced (neither threshold met).",
      "error_conditions": []
    },
    {
      "name": "DiscoveredCategory",
      "signature": "pub struct DiscoveredCategory { pub member_count: usize, pub member_session_ids: Vec<CompactString>, pub tool_bigram_fingerprint: Vec<CompactString> }",
      "description": "A dynamically discovered workflow cluster of >= 3 transcripts whose ordered tool-invocation sequences meet the pairwise similarity threshold in CRIT-LUMEN-156.",
      "error_conditions": []
    },
    {
      "name": "RtkOpportunityRule",
      "signature": "pub struct RtkOpportunityRule; impl RtkOpportunityRule { pub fn evaluate(commands: &[CommandEventRecord]) -> Vec<StructuredFinding>; }",
      "description": "Evaluates command event sequences to detect legacy POSIX tool invocations (grep, find, cat, cd) and generate actionable modern CLI recommendations.",
      "error_conditions": []
    },
    {
      "name": "FindingGenerator",
      "signature": "pub struct FindingGenerator; impl FindingGenerator { pub fn generate_findings(transcript: &CanonicalTranscript, loop_anomalies: &[CycleAnomaly]) -> Vec<StructuredFinding>; }",
      "description": "Synthesizes structured findings containing severity, confidence, rule version, evidence JSON, and remediation recommendations.",
      "error_conditions": []
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-LUMEN-080",
      "criterion": "WHEN a session's mutation_density (count of ToolIntent::FileEdit and ToolIntent::FileCreate calls divided by total tool calls in the session; ToolIntent::VersionControl is excluded from this ratio since its actions span both read-only and mutating operations) is >= 0.60 AND its search_turn_count (count of turns containing at least one ToolIntent::CodeSearch or ToolIntent::FileDiscovery call) is <= 2, THE SYSTEM SHALL classify its bimodal mode as BimodalMode::Acceleration.",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-081",
      "criterion": "WHEN a session's search_turn_count (count of turns containing at least one ToolIntent::CodeSearch or ToolIntent::FileDiscovery call) is >= 6 AND its total turn_count is >= 15, THE SYSTEM SHALL classify its bimodal mode as BimodalMode::Exploration.",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-082",
      "criterion": "WHEN a command event sequence contains grep or egrep invocations, THE SYSTEM SHALL emit an RTK opportunity finding recommending ripgrep (rg) with an estimated speedup metric.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-083",
      "criterion": "WHEN a command event sequence contains find invocations, THE SYSTEM SHALL emit an RTK opportunity finding recommending fd to prevent traversing ignored build directories.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-084",
      "criterion": "WHEN structured findings are generated, THE SYSTEM SHALL populate evidence_json, confidence score in [0.0, 1.0], rule_or_model_version, and actionable recommendation text.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-085",
      "criterion": "WHEN computing periodic rollups, THE SYSTEM SHALL aggregate session count, total cost USD, active wall time, and finding counts by repository, category, and weekly period start.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-156",
      "criterion": "WHEN WorkflowClassifier::discover_fingerprint_corpus evaluates a corpus of transcripts and finds a maximal clique of >= 3 transcripts where every pair within the clique has Jaccard similarity >= 0.75 over the set of tool-name bigrams extracted from each transcript's ordered ToolIntent call sequence (complete-linkage clustering), THE SYSTEM SHALL emit one DiscoveredCategory per maximal qualifying clique with member_count equal to the clique size and member_session_ids listing every member transcript's session_id; a transcript belonging to more than one qualifying clique SHALL be assigned only to the largest, ties broken by lexically earliest session_id. WorkflowClassifier::discover_fingerprint(transcript, corpus) SHALL return Some(that DiscoveredCategory) for any transcript present in corpus that was assigned to a clique.",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-157",
      "criterion": "IF no maximal clique of >= 3 transcripts in the corpus meets the >= 0.75 pairwise tool-bigram similarity threshold, THE SYSTEM SHALL have discover_fingerprint_corpus return an empty Vec<DiscoveredCategory>, and discover_fingerprint(transcript, corpus) SHALL return None for every transcript in that corpus.",
      "is_error_case": true,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-158",
      "criterion": "WHEN a session's mutation_density, search_turn_count, and turn_count satisfy neither CRIT-LUMEN-080's Acceleration thresholds nor CRIT-LUMEN-081's Exploration thresholds, THE SYSTEM SHALL classify its bimodal mode as BimodalMode::Balanced.",
      "is_error_case": false,
      "judgment_call": false
    }
  ],
  "linked_requirement": "REQ-LUMEN-007",
  "linked_research": "RES-LUMEN-001",
  "spec_file_path": "specs/SPEC-LUMEN-007-INSIGHTS.json",
  "reasoning": "Establishes workflow categorization, bimodal theory modeling, RTK missed savings coaching, and structured finding generation."
}

