{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "spec@1",
  "id": "SPEC-LUMEN-001-MODEL",
  "purpose": "Defines the canonical domain primitives, token economics, pricing matrix, and intermediate representation (IR) types for the Lumen session intelligence and Prism evaluation platforms.",
  "scope": "Covers crates/lumen-model: CanonicalTranscript, CanonicalTurn, ToolIntent, TurnRole, TurnTokenUsage, ModelPricing, TokenEconomics, ModelTokenSummary, ExecutionTiming, TrajectoryAnomaly, and SchemaCitation.",
  "non_goals": [
    "Log file ingestion, disk I/O, or format parsing (delegated to lumen-session).",
    "Stateful metric accumulation or anomaly detection algorithms (delegated to lumen-analysis and lumen-pattern).",
    "Evaluation assertion grading or test execution (delegated to prism-grader).",
    "Extended-TTL (1-hour) prompt cache pricing tiers for the six non-Anthropic providers (GPT-4o, DeepSeek, Qwen, Kimi, GLM, Gemini): none of these providers publish a selectable 1h-cache rate today, so no criterion can be written that is verifiable against a real published price. TokenEconomics.ephemeral_1h_tokens is intentionally unpopulated (hardcoded to 0) pending a future Anthropic-specific 1h-cache criterion, which would be scoped separately since Anthropic is the only provider with a real, selectable extended-TTL cache tier.",
    "Re-verifying the specific per-provider dollar rate VALUES in PricingTable::seed() against current published pricing: this pass corrects only the pricing ARCHITECTURE (hardcoded match statement -> versioned, timestamped rate table), carrying forward the exact same dollar amounts CRIT-LUMEN-002 through 105 already specify. Those values were already flagged in an earlier research pass as possibly stale versus real published rates for the six non-Anthropic providers; this pass does not re-research or correct them -- a dedicated pricing-refresh pass (ideally sourced from a live feed per OpenRouter/LiteLLM, researched 2026-08-20) is required separately before the seed values themselves can be trusted as accurate."
  ],
  "api_surface": [
    {
      "name": "CanonicalTranscript",
      "signature": "pub struct CanonicalTranscript { pub session_id: CompactString, pub parent_session_id: Option<CompactString>, pub orchestrator: OrchestratorKind, pub model_family: CompactString, pub timing: ExecutionTiming, pub economics: TokenEconomics, pub turns: Vec<CanonicalTurn>, pub subagents: Vec<CanonicalTranscript>, pub extracted_schemas: SmallVec<[SchemaCitation; 4]>, pub detected_anomalies: SmallVec<[TrajectoryAnomaly; 4]> }",
      "description": "Universal normalized transcript representation holding the complete conversation tree, subagent hierarchy, token economics, and extracted schema artifacts.",
      "error_conditions": [
        "Deserialization error if JSON payload violates field types"
      ]
    },
    {
      "name": "CanonicalTurn",
      "signature": "pub struct CanonicalTurn { pub turn_index: usize, pub role: TurnRole, pub timestamp: DateTime<Utc>, pub latency_ms: u64, pub text: Option<String>, pub tool_calls: SmallVec<[CanonicalToolCall; 2]>, pub tool_results: SmallVec<[CanonicalToolResult; 2]>, pub usage: Option<TurnTokenUsage> }",
      "description": "Normalized user, assistant, system, or tool execution turn.",
      "error_conditions": []
    },
    {
      "name": "PricingRate / PricingTable",
      "signature": "pub enum TokenRateKind { Input, CacheWrite, CacheRead, Output }; pub struct PricingRate { pub model: CompactString, pub kind: TokenRateKind, pub rate_per_m: f64, pub effective_from: DateTime<Utc>, pub effective_until: Option<DateTime<Utc>> }; pub struct PricingTable { pub rates: Vec<PricingRate> }; impl PricingTable { pub fn seed() -> Self; pub fn rate_for(&self, model: &str, kind: TokenRateKind, as_of: DateTime<Utc>) -> f64; }",
      "description": "Versioned exchange-rate-style pricing lookup: rate_for selects the PricingRate row for (model, kind) whose [effective_from, effective_until) window contains as_of -- the token-generating turn's own timestamp, never the current wall-clock time -- so historical costs stay correct after a provider changes prices. Replaces the prior hardcoded from_model_name match statement; PricingTable::seed() ships the same rate values previously hardcoded in ModelPricing, now as dated rows instead of match arms. Cross-validated against Langfuse's real Price/PricingTier tables and ccusage's timestamp-gated Kimi pricing cutoff (both real systems, researched 2026-08-20).",
      "error_conditions": [
        "IF no PricingRate row's window contains as_of for the given (model, kind), THE SYSTEM SHALL fall back to CLAUDE_3_5_SONNET's seed rate for that kind (same fallback model as CRIT-LUMEN-008), never panicking or silently returning 0.0"
      ]
    },
    {
      "name": "TokenEconomics",
      "signature": "pub struct TokenEconomics { pub input_tokens: u64, pub output_tokens: u64, pub cache_creation_tokens: u64, pub cache_read_tokens: u64, pub ephemeral_5m_tokens: u64, pub ephemeral_1h_tokens: u64, pub cache_hit_ratio: f32, pub total_cost_usd: f64, pub provided_cost_usd: Option<f64>, pub baseline_cost_no_cache_usd: f64, pub net_savings_usd: f64, pub efficiency_multiplier: f32, pub per_model: HashMap<CompactString, ModelTokenSummary> }; impl TokenEconomics { pub fn calculate(input_tokens: u64, output_tokens: u64, cache_creation_tokens: u64, cache_read_tokens: u64, model_name: &str, as_of: DateTime<Utc>, pricing: &PricingTable, provided_cost_usd: Option<f64>) -> Self; }",
      "description": "Aggregated session economics calculating exact financial costs (via PricingTable::rate_for at the turn's as_of timestamp), prompt cache hit ratios, net USD savings, and financial efficiency multipliers. provided_cost_usd carries the source's own reported cost (e.g. Claude Code's real costUSD field, confirmed present via ccusage) verbatim alongside the independently computed total_cost_usd, mirroring Langfuse's raw-vs-canonicalized twin-field pattern -- enables drift detection between what the provider billed and what Lumen computed, never used to override total_cost_usd.",
      "error_conditions": [
        "Sets cache_hit_ratio to 0.0 and efficiency_multiplier to 1.0 if total prompt tokens is zero",
        "Sets provided_cost_usd to None when the source record carries no provider-reported cost field, never defaulting it to 0.0"
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-LUMEN-001",
      "criterion": "WHEN CanonicalTranscript is serialized to JSON and deserialized back to Rust, THE SYSTEM SHALL preserve identical struct equality with zero data loss.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-002",
      "criterion": "WHEN computing Claude 3.5 Sonnet costs, THE SYSTEM SHALL bill uncached inputs at $3.00/M, cache creation writes at $3.75/M (1.25x), cache reads at $0.30/M (0.10x), and output tokens at $15.00/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-003",
      "criterion": "WHEN computing Claude 3.5 Haiku costs, THE SYSTEM SHALL bill uncached inputs at $0.80/M, cache creation writes at $1.00/M (1.25x), cache reads at $0.08/M (0.10x), and output tokens at $4.00/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-004",
      "criterion": "WHEN computing Qwen 2.5 Coder costs, THE SYSTEM SHALL bill uncached inputs at $0.20/M, cache reads at $0.05/M, and output tokens at $0.60/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-005",
      "criterion": "WHEN computing prompt cache hit ratio H, THE SYSTEM SHALL calculate H = (cache_read_tokens / (input_tokens + cache_creation_tokens + cache_read_tokens)) * 100.0.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-006",
      "criterion": "WHEN computing financial efficiency multiplier eta, THE SYSTEM SHALL calculate eta = baseline_cost_no_cache_usd / total_cost_usd.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-007",
      "criterion": "IF total prompt tokens is zero, THE SYSTEM SHALL return cache_hit_ratio of 0.0 and efficiency_multiplier of 1.0 without dividing by zero.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-008",
      "criterion": "WHEN an unrecognized model string is passed to ModelPricing::from_model_name, THE SYSTEM SHALL default to Claude 3.5 Sonnet pricing rates.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-009",
      "criterion": "WHEN calculating net USD savings, THE SYSTEM SHALL ensure net_savings_usd is clamped to a minimum of 0.0.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-010",
      "criterion": "WHEN TurnTokenUsage calculates prompt_tokens, THE SYSTEM SHALL return the sum of input_tokens, cache_creation_tokens, and cache_read_tokens.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-099",
      "criterion": "WHEN computing Claude Opus costs, THE SYSTEM SHALL bill uncached inputs at $15.00/M, cache creation writes at $18.75/M (1.25x), cache reads at $1.50/M (0.10x), and output tokens at $75.00/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-100",
      "criterion": "WHEN computing GPT-4o costs, THE SYSTEM SHALL bill uncached inputs at $2.50/M, cache creation writes at $2.50/M (same as the uncached input rate), cache reads at $1.25/M, and output tokens at $10.00/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-101",
      "criterion": "WHEN computing DeepSeek R1 costs, THE SYSTEM SHALL bill uncached inputs at $0.55/M, cache creation writes at $0.55/M (same as the uncached input rate), cache reads at $0.14/M, and output tokens at $2.19/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-102",
      "criterion": "WHEN computing Kimi K1.5 costs, THE SYSTEM SHALL bill uncached inputs at $0.50/M, cache creation writes at $0.50/M (same as the uncached input rate), cache reads at $0.10/M, and output tokens at $2.00/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-103",
      "criterion": "WHEN computing GLM-4-Plus costs, THE SYSTEM SHALL bill uncached inputs at $1.40/M, cache creation writes at $1.40/M (same as the uncached input rate), cache reads at $0.20/M, and output tokens at $1.40/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-104",
      "criterion": "WHEN computing Gemini 2.0 Flash costs, THE SYSTEM SHALL bill uncached inputs at $0.10/M, cache creation writes at $0.10/M (same as the uncached input rate), cache reads at $0.025/M, and output tokens at $0.40/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-105",
      "criterion": "WHEN computing Gemini 2.0 Pro costs, THE SYSTEM SHALL bill uncached inputs at $1.25/M, cache creation writes at $1.25/M (same as the uncached input rate), cache reads at $0.30/M, and output tokens at $5.00/M.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-159",
      "criterion": "WHEN PricingTable::rate_for(model, kind, as_of) is invoked, THE SYSTEM SHALL select the PricingRate row for that (model, kind) pair whose effective_from is less than or equal to as_of AND whose effective_until is either None or strictly greater than as_of, using the turn's own recorded timestamp as as_of -- never the current wall-clock time -- so that a session's cost reflects the rate in effect when the tokens were actually billed, not today's rate. IF more than one row matches (an overlapping-window authoring error), THE SYSTEM SHALL select the row with the latest effective_from.",
      "is_error_case": false,
      "judgment_call": true,
      "reasoning": "Establishes the exchange-rate lookup semantics: this is the general mechanism, not restated per-provider, since CRIT-LUMEN-002 through 105's dollar amounts remain correct observable-behavior statements regardless of whether they're realized via a match statement or a table lookup -- those criteria are unchanged by this pass. Design confirmed directly by the user (2026-08-20) using an FX historical-rate-lookup analogy, cross-validated against Langfuse's real Price/PricingTier schema and ccusage's Kimi timestamp-gated pricing cutoff."
    },
    {
      "id": "CRIT-LUMEN-160",
      "criterion": "IF a raw usage record supplied to TokenEconomics::calculate carries a provider-reported cost value (e.g. Claude Code's real costUSD field), THE SYSTEM SHALL store it verbatim in TokenEconomics.provided_cost_usd; THE SYSTEM SHALL NOT use provided_cost_usd to override, blend with, or short-circuit the independently computed total_cost_usd -- the two fields exist to be compared for drift, not merged.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-161",
      "criterion": "IF PricingTable::rate_for finds no PricingRate row whose window contains as_of for the requested (model, kind), THE SYSTEM SHALL fall back to CLAUDE_3_5_SONNET's seed rate for that kind (the same default model CRIT-LUMEN-008 already specifies for an unrecognized model string), and SHALL NOT panic or silently return 0.0.",
      "is_error_case": true,
      "judgment_call": false
    }
  ],
  "linked_requirement": "REQ-LUMEN-001",
  "linked_research": "RES-LUMEN-001",
  "spec_file_path": "specs/SPEC-LUMEN-001-MODEL.json",
  "reasoning": "Establishes the foundational type system, token accounting formulas, and expanded pricing matrices (Sonnet, Haiku, Opus, GPT-4o, DeepSeek, Qwen, Kimi, GLM, Gemini) required for downstream analysis."
}

